import unittest

from solucao import pegar_letra


class TestOTextoTemPosicaoTambem(unittest.TestCase):
    def test_pega_a_primeira_letra(self):
        """pegar_letra devolve a letra da posicao 0"""
        self.assertEqual(pegar_letra("banana", 0), "b")

    def test_pega_no_meio(self):
        """pegar_letra devolve a letra da posicao 2"""
        self.assertEqual(pegar_letra("banana", 2), "n")

    def test_volta_ao_comeco(self):
        """pegar_letra volta ao comeco quando a posicao passa do fim"""
        self.assertEqual(pegar_letra("banana", 6), "b")

    def test_volta_com_sobra(self):
        """pegar_letra usa o resto da posicao depois de voltar ao comeco"""
        self.assertEqual(pegar_letra("ola", 4), "l")
